"""
Automated regression suite generated by VerityQA from an evidence-grounded test plan.
Target application: http://127.0.0.1:8201/
Target origin: http://127.0.0.1:8201
Requirements: pip install pytest playwright && python -m playwright install chromium
Run: pytest -v <this_file.py>
Credentials (only for tests that need them): VERITYQA_TEST_CREDENTIALS_ORIGIN, VERITYQA_TEST_USERNAME,
VERITYQA_TEST_PASSWORD. Outcomes: passed = all oracles held; failed = an oracle was violated;
skipped BLOCKED/INCOMPLETE/INVALID = not a verdict.
"""
import json
import os
import re
import secrets

import pytest
from playwright.sync_api import Page, expect, sync_playwright

TARGET_ORIGIN = 'http://127.0.0.1:8201'
UNIQUE_TOKEN = '${RUN_UNIQUE}'
AUTH_DISCOVERY_SCRIPT = '\n() => {\n  const visible = el => !!el && el.getClientRects().length > 0 && getComputedStyle(el).visibility !== \'hidden\';\n  const esc = v => (window.CSS && CSS.escape) ? CSS.escape(v) : v;\n  // Structural path for elements without id/name (validated against the DOM before use by the caller).\n  const path = el => {\n    const parts = [];\n    for (let n = el; n && n.nodeType === 1 && n !== document.body; n = n.parentElement) {\n      if (n.id) { parts.unshift(\'#\' + esc(n.id)); return parts.join(\' > \'); }\n      const same = Array.from(n.parentElement ? n.parentElement.children : []).filter(k => k.tagName === n.tagName);\n      parts.unshift(n.tagName.toLowerCase() + (same.length > 1 ? \':nth-of-type(\' + (same.indexOf(n) + 1) + \')\' : \'\'));\n    }\n    return \'body > \' + parts.join(\' > \');\n  };\n  const sel = el => {\n    if (el.id) return \'#\' + esc(el.id);\n    if (el.name && document.querySelectorAll(el.tagName.toLowerCase() + \'[name="\' + el.name + \'"]\').length === 1)\n      return el.tagName.toLowerCase() + \'[name="\' + el.name + \'"]\';\n    return path(el);\n  };\n  const labelOf = el => {\n    const l = el.id ? document.querySelector(\'label[for="\' + esc(el.id) + \'"]\') : null;\n    return ((l && l.innerText) || el.getAttribute(\'aria-label\') || el.placeholder || el.name || el.id || \'\').trim().toLowerCase();\n  };\n  const containers = Array.from(document.querySelectorAll(\'form\'));\n  // Pages without <form>: treat the nearest common ancestor of a lone password field as the container.\n  if (!containers.length) {\n    const p = Array.from(document.querySelectorAll(\'input[type=password]\')).find(visible);\n    if (p) containers.push(p.closest(\'div, section, main, body\'));\n  }\n  const forms = containers.map((f, i) => {\n    const inputs = Array.from(f.querySelectorAll(\'input, select, textarea\')).filter(visible);\n    const pw = inputs.filter(x => (x.type || \'\').toLowerCase() === \'password\');\n    const ident = inputs.filter(x => [\'text\', \'email\', \'tel\', \'\'].includes((x.type || \'\').toLowerCase()) && x.tagName === \'INPUT\');\n    const user = ident.find(x => /user|email|login|account|name|mail|id/.test(labelOf(x))) || ident[0] || null;\n    const submit = Array.from(f.querySelectorAll(\'button, input[type=submit], input[type=button], [role=button]\'))\n      .filter(visible).find(b => (b.type || \'\').toLowerCase() === \'submit\' || /log\\s*in|sign\\s*in|continue|submit|enter/i.test(b.innerText || b.value || \'\'));\n    const words = ((f.getAttribute && (f.getAttribute(\'action\') || \'\') + \' \' + (f.id || \'\') + \' \' + (f.className || \'\')) || \'\').toLowerCase();\n    return {\n      index: i, password_count: pw.length, identity_count: ident.length,\n      username_selector: user ? sel(user) : null, password_selector: pw[0] ? sel(pw[0]) : null,\n      submit_selector: submit ? sel(submit) : null,\n      submit_text: submit ? (submit.innerText || submit.value || \'\').trim().slice(0, 40) : \'\',\n      login_words: /log\\s*in|sign\\s*in|signin|login|session|auth/.test(words + \' \' + (submit ? (submit.innerText || submit.value || \'\') : \'\')),\n    };\n  });\n  const challenge = (() => {\n    if (document.querySelector(\'iframe[src*="recaptcha"], iframe[src*="hcaptcha"], iframe[src*="turnstile"], .g-recaptcha, .h-captcha, [data-sitekey]\')) return \'CAPTCHA\';\n    const mfa = Array.from(document.querySelectorAll(\'input\')).filter(visible).find(x =>\n      (x.autocomplete || \'\').toLowerCase() === \'one-time-code\' || /otp|totp|2fa|mfa|one.?time|verification.?code|authenticator/i.test((x.name || \'\') + \' \' + (x.id || \'\') + \' \' + labelOf(x)));\n    return mfa ? \'MFA\' : null;\n  })();\n  const errSel = \'[role="alert"], [data-test=error], .error-message, .error, .alert-danger, .alert-error, .invalid-feedback, .field-error\';\n  const err = Array.from(document.querySelectorAll(errSel)).find(e => visible(e) && (e.innerText || \'\').trim());\n  const links = Array.from(document.querySelectorAll(\'a[href]\')).filter(visible)\n    .filter(a => /log\\s*in|sign\\s*in/i.test(a.innerText || \'\') || /login|signin|sign-in/i.test(a.getAttribute(\'href\')))\n    .map(a => a.href).slice(0, 3);\n  return {\n    forms: forms, challenge: challenge, error: err ? err.innerText.trim().slice(0, 120) : null, login_links: links,\n    password_visible: Array.from(document.querySelectorAll(\'input[type=password]\')).some(visible),\n    logout_visible: Array.from(document.querySelectorAll(\'a, button\')).some(el => visible(el) && /log\\s*out|sign\\s*out/i.test(el.textContent || el.id || \'\')),\n  };\n}\n'
COLLECTION_SCRIPT = '\n(args) => {\n  const key = args.key;\n  // Cells are fields of a record, never records themselves.\n  const skipTags = new Set([\'A\', \'BUTTON\', \'OPTION\', \'LABEL\', \'INPUT\', \'SCRIPT\', \'STYLE\', \'BR\', \'SELECT\', \'TH\', \'TD\']);\n  const chrome = \'nav, header, footer, select, datalist, [role="navigation"], [role="menu"], [aria-hidden="true"]\';\n  const sig = el => el.tagName + \'.\' + (typeof el.className === \'string\'\n      ? el.className.trim().split(/\\s+/).filter(c => c && !/^(active|selected|current|odd|even)$/i.test(c)).sort().join(\'.\') : \'\');\n  const shown = el => el.tagName === \'TR\' ? el.getClientRects().length > 0 : el.offsetParent !== null;\n  const numberOf = t => {\n    const m = t.match(/[$\\u20ac\\u00a3\\u20b9]\\s*-?\\d[\\d,]*(?:\\.\\d+)?/) || t.match(/-?\\d[\\d,]*(?:\\.\\d+)?/);\n    return m ? parseFloat(m[0].replace(/[^\\d.\\-]/g, \'\')) : null;\n  };\n  const primaryText = el => {\n    const p = el.querySelector(\'[class*="name"], [class*="title"], h1, h2, h3, h4, h5, a, strong, b\');\n    const t = ((p && p.innerText) || el.innerText || \'\').trim();\n    return t.split(\'\\n\')[0].trim();\n  };\n  // A record\'s own fields: table cells for rows, otherwise its leaf elements\' texts.\n  const fieldsOf = el => el.tagName === \'TR\'\n      ? Array.from(el.cells).map(c => (c.innerText || \'\').trim())\n      : Array.from(el.querySelectorAll(\'*\')).filter(n => n.children.length === 0)\n          .map(n => (n.innerText || n.textContent || \'\').trim()).filter(t => t);\n  const headersOf = el => {\n    const table = el.tagName === \'TR\' ? el.closest(\'table\') : null;\n    if (!table) return [];\n    const head = table.querySelectorAll(\'thead th\');\n    const cells = head.length ? head : (table.querySelector(\'tr\') ? table.querySelector(\'tr\').querySelectorAll(\'th\') : []);\n    return Array.from(cells).map(h => (h.innerText || \'\').trim());\n  };\n  let best = null;\n  for (const parent of document.querySelectorAll(\'body *\')) {\n    if (parent.closest(chrome)) continue;\n    const kids = Array.from(parent.children).filter(k => !skipTags.has(k.tagName) && shown(k) && !k.querySelector(\'th\'));\n    if (kids.length < 2) continue;\n    const counts = {};\n    kids.forEach(k => { const s = sig(k); counts[s] = (counts[s] || 0) + 1; });\n    const top = Object.entries(counts).sort((a, b) => b[1] - a[1])[0];\n    if (!top || top[1] < 2) continue;\n    const items = kids.filter(k => sig(k) === top[0] && (k.innerText || \'\').trim().length > 0);\n    if (items.length < 2) continue;\n    const values = items.map(it => key === \'number\' ? numberOf(it.innerText || \'\') : primaryText(it)).filter(v => v !== null && v !== \'\');\n    if (values.length < items.length) continue;\n    const avgLen = items.reduce((n, it) => n + (it.innerText || \'\').length, 0) / items.length;\n    const score = items.length + (items[0].tagName === \'TR\' || items[0].tagName === \'LI\' ? 0.5 : 0) + (avgLen > 20 ? 0.75 : 0);\n    if (!best || score > best.score) {\n      best = {score: score, values: values, texts: items.map(it => (it.innerText || \'\').replace(/\\s+/g, \' \').trim()),\n              fields: items.map(fieldsOf), headers: headersOf(items[0]), signature: top[0]};\n    }\n  }\n  return best || {values: [], texts: [], signature: null};\n}\n'
TEXT_ANOMALY_PATTERNS = ('(?m)(?:^|[:=$€£₹])[ \\t]*NaN\\b', '(?m)(?:^|[:=$€£₹])[ \\t]*undefined\\b', '\\[object Object\\]', 'Traceback \\(most recent call last\\)')
RECORD_SNAPSHOT_SCRIPT = '\n(sel) => {\n  const el = document.querySelector(sel);\n  if (!el) return null;\n  const norm = t => (t || \'\').replace(/\\s+/g, \' \').trim();\n  let rec = el.closest(\'tr, li, article, [role="row"], [role="listitem"]\');\n  for (let a = el.parentElement; !rec && a && a !== document.body; a = a.parentElement) {\n    const p = a.parentElement;\n    if (p && Array.from(p.children).filter(k => k.tagName === a.tagName && k.className === a.className).length >= 2) rec = a;\n  }\n  if (!rec || !rec.parentElement) return null;\n  const text = norm(rec.innerText);\n  const count = Array.from(rec.parentElement.children).filter(k => k.tagName === rec.tagName && norm(k.innerText) === text).length;\n  return {id: rec.id || \'\', tag: rec.tagName, text: text, count: count};\n}\n'
RECORD_COUNT_SCRIPT = "\n(s) => {\n  const norm = t => (t || '').replace(/\\s+/g, ' ').trim();\n  if (s.id) {\n    const r = document.getElementById(s.id);\n    return r && norm(r.innerText) === s.text ? 1 : 0;\n  }\n  return Array.from(document.querySelectorAll(s.tag)).filter(k => norm(k.innerText) === s.text).length;\n}\n"

STATUS = {"last": None}


@pytest.fixture
def page():
    """Isolated Chromium page per test."""
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=os.environ.get("VERITYQA_HEADED") != "1")
        context = browser.new_context(viewport={"width": 1280, "height": 800})
        pg = context.new_page()
        pg.set_default_timeout(int(os.environ.get("VERITYQA_TIMEOUT_MS", "8000")))
        STATUS["last"] = None

        def _on_response(resp):
            try:
                if resp.request.resource_type == "document" and resp.frame == pg.main_frame:
                    STATUS["last"] = resp.status
            except Exception:
                pass

        pg.on("response", _on_response)
        yield pg
        context.close()
        browser.close()


def credential(kind):
    """Origin-scoped credential from the environment; the test is BLOCKED (skipped) without one."""
    # A website profile whose ORIGIN is exactly this target (VERITYQA_CREDENTIALS_<PROFILE>_ORIGIN/_USERNAME/_PASSWORD).
    profiles = [k[len("VERITYQA_CREDENTIALS_"):-len("_ORIGIN")] for k, v in os.environ.items()
                if k.startswith("VERITYQA_CREDENTIALS_") and k.endswith("_ORIGIN") and v.rstrip("/") == TARGET_ORIGIN]
    if len(profiles) == 1 and os.environ.get(f"VERITYQA_CREDENTIALS_{profiles[0]}_{kind.upper()}"):
        return os.environ[f"VERITYQA_CREDENTIALS_{profiles[0]}_{kind.upper()}"]
    if os.environ.get("VERITYQA_TEST_CREDENTIALS_ORIGIN", "").rstrip("/") != TARGET_ORIGIN:
        pytest.skip(f"BLOCKED: no credentials authorized for {TARGET_ORIGIN} (set VERITYQA_TEST_CREDENTIALS_ORIGIN)")
    value = os.environ.get("VERITYQA_TEST_" + kind.upper())
    if not value:
        pytest.skip(f"BLOCKED: VERITYQA_TEST_{kind.upper()} is not set")
    return value


def unique(value, token):
    """Per-test unique data: identity values never collide with records an earlier run created."""
    return value.replace(UNIQUE_TOKEN, token)


def record_changed(page, snapshot):
    """The record a command acted on must be removed or changed (same semantics as the executor)."""
    if not snapshot:
        incomplete("the control is not inside a repeated record (row, item or card)")
    page.wait_for_load_state("domcontentloaded")
    count = page.evaluate(RECORD_COUNT_SCRIPT, snapshot)
    assert count < (1 if snapshot.get("id") else snapshot.get("count", 1)),         f"Record unchanged after the action: {snapshot['text'][:120]!r}"


def setup_check(kind, page, selector, expected):
    """A prerequisite's check: failing it means the behaviour under test was never reached (BLOCKED)."""
    try:
        check(kind, page, selector, expected)
    except AssertionError as err:
        pytest.skip(f"BLOCKED: SETUP_FAILED: {err}")


def setup_fill(page, selector, value):
    """Fill a prerequisite field and require that it keeps the value (lengths only in the message)."""
    page.locator(selector).first.fill(value)
    kept = page.locator(selector).first.input_value()
    if kept != value:
        pytest.skip(f"BLOCKED: SETUP_FAILED: field {selector} holds {len(kept)} chars after filling {len(value)}")


def _page_path(url):
    from urllib.parse import urlsplit
    return urlsplit(url).path.rstrip("/") or "/"


def _login_gate(seen):
    return bool(seen.get("challenge")) or any(f["password_count"] == 1 and f["identity_count"] >= 1 for f in seen.get("forms", []))


def open_page(page, url, requires_login=False, login_url=None):
    """Reach a page with the authentication it needs (same rules as VerityQA's executor); BLOCKED skips otherwise."""
    page.goto(url, wait_until="domcontentloaded")
    seen = page.evaluate(AUTH_DISCOVERY_SCRIPT)
    gate = _page_path(page.url) != _page_path(url) and _login_gate(seen)
    if not gate and (not requires_login or seen.get("logout_visible")):
        return
    username, password = credential("username"), credential("password")   # skips as BLOCKED when not configured
    if not gate and login_url:
        page.goto(login_url, wait_until="domcontentloaded")
        seen = page.evaluate(AUTH_DISCOVERY_SCRIPT)
    if seen.get("challenge"):
        pytest.skip(f"BLOCKED: AUTH_UNRESOLVED: {seen['challenge']} challenge; automated login is not attempted")
    forms = [f for f in seen.get("forms", []) if f["password_count"] == 1 and f["identity_count"] >= 1
             and f["username_selector"] and f["password_selector"]]
    if len(forms) > 1 and len([f for f in forms if f["login_words"]]) == 1:
        forms = [f for f in forms if f["login_words"]]
    if len(forms) != 1:
        pytest.skip(f"BLOCKED: AUTH_UNRESOLVED: {len(forms)} candidate login forms")
    form = forms[0]
    page.locator(form["username_selector"]).first.fill(username)
    page.locator(form["password_selector"]).first.fill(password)
    if form["submit_selector"]:
        page.locator(form["submit_selector"]).first.click()
    else:
        page.locator(form["password_selector"]).first.press("Enter")
    page.wait_for_load_state("domcontentloaded")
    after = page.evaluate(AUTH_DISCOVERY_SCRIPT)
    if after.get("error") or after.get("password_visible"):
        pytest.skip("BLOCKED: LOGIN_FAILED: " + (after.get("error") or "login form still present"))
    page.goto(url, wait_until="domcontentloaded")
    if _page_path(page.url) != _page_path(url):
        pytest.skip(f"BLOCKED: required page not reached after login (landed on {page.url})")


def incomplete(reason):
    pytest.skip("INCOMPLETE: " + reason)


def check(kind, page, selector, expected):
    """Evaluates one oracle with the same semantics as the VerityQA BrowserExecutor."""
    if kind == "URL_CONTAINS":
        assert expected.lower() in page.url.lower(), f"Expected URL to contain {expected!r}, got {page.url!r}"
    elif kind == "URL_EQUALS":
        assert page.url == expected, f"Expected URL {expected!r}, got {page.url!r}"
    elif kind == "TEXT_VISIBLE":
        scope = page.locator(selector) if selector else page.locator("body")
        expect(scope.get_by_text(expected, exact=False).first).to_be_visible()
    elif kind == "TEXT_NOT_VISIBLE":
        scope = page.locator(selector) if selector else page.locator("body")
        expect(scope.get_by_text(expected, exact=False).first).not_to_be_visible()
    elif kind == "ELEMENT_VISIBLE":
        expect(page.locator(selector).first).to_be_visible()
    elif kind == "ELEMENT_NOT_VISIBLE":
        expect(page.locator(selector).first).not_to_be_visible()
    elif kind == "ELEMENT_DISABLED":
        expect(page.locator(selector).first).to_be_disabled()
    elif kind == "ELEMENT_ENABLED":
        expect(page.locator(selector).first).to_be_enabled()
    elif kind == "STATUS_CODE":
        status = STATUS["last"]
        if status is None:
            incomplete("no document response status was captured")
        m = re.match(r"^\s*(<=|>=|<|>|==)?\s*(\d{3})\s*$", expected)
        op, num = (m.group(1) or "=="), int(m.group(2))
        ok = {"<": status < num, "<=": status <= num, ">": status > num, ">=": status >= num, "==": status == num}[op]
        assert ok, f"Expected HTTP status {op}{num}, got {status}"
    elif kind == "FIELD_VALIDITY":
        res = page.evaluate("""(sel) => { const el = document.querySelector(sel); if (!el || !el.validity) return null;
            const v = el.validity; return {valid: v.valid, flags: ['valueMissing','typeMismatch','patternMismatch','tooLong',
            'tooShort','rangeUnderflow','rangeOverflow','stepMismatch','badInput'].filter(k => v[k])}; }""", selector)
        assert res is not None, f"Field {selector!r} is not present (the form may have been submitted)"
        if expected == "valid":
            assert res["valid"], f"Expected {selector!r} to be valid, flags={res['flags']}"
        elif expected == "invalid":
            assert not res["valid"], f"Expected {selector!r} to be invalid"
        else:
            assert expected in res["flags"], f"Expected validity {expected!r} on {selector!r}, flags={res['flags']}"
    elif kind == "ELEMENT_VALUE_LENGTH":
        length = page.evaluate("(sel) => { const el = document.querySelector(sel); return el ? (el.value || '').length : null; }", selector)
        assert length is not None, f"Field {selector!r} is not present"
        m = re.match(r"^\s*(<=|>=|==)?\s*(\d+)\s*$", expected)
        op, num = (m.group(1) or "=="), int(m.group(2))
        assert {"<=": length <= num, ">=": length >= num, "==": length == num}[op], f"Expected length {op}{num}, got {length}"
    elif kind in ("VALIDATION_FEEDBACK_SHOWN", "NO_VALIDATION_FEEDBACK"):
        page.wait_for_load_state("domcontentloaded")
        feedback = page.evaluate("""(sel) => { const out = []; const visible = el => !!(el && el.offsetParent !== null && (el.innerText || '').trim());
            const f = sel ? document.querySelector(sel) : null;
            if (f && f.validity && !f.validity.valid) out.push('field invalid'); if (f && f.getAttribute('aria-invalid') === 'true') out.push('aria-invalid');
            for (const m of document.querySelectorAll('[role="alert"], .error, .errors, .error-message, .invalid-feedback, .alert-danger, .field-error, .validation-error, [class*="error-message"], [data-test="error"], [aria-live="assertive"]'))
              if (visible(m)) out.push('message: ' + m.innerText.trim().slice(0, 120)); return out; }""", selector or "")
        keywords = [k.lower() for k in json.loads(expected)] if expected.strip().startswith("[") else []
        attributable = [f for f in feedback if not f.startswith("message: ") or not keywords or any(k in f.lower() for k in keywords)]
        if kind == "VALIDATION_FEEDBACK_SHOWN":
            assert attributable, f"Expected feedback attributable to this rule; shown: {feedback or 'none'}"
        else:
            assert not attributable, f"Expected the submission to be accepted, but rule feedback was shown: {attributable}"
    elif kind == "SELECTED_VALUE":
        assert page.evaluate("(sel) => { const el = document.querySelector(sel); return el ? el.value : null; }", selector) == expected
    elif kind in ("LIST_SORTED", "LIST_ALL_CONTAIN"):
        page.wait_for_load_state("domcontentloaded")
        structured = kind == "LIST_SORTED" or expected.lstrip().startswith("{")
        spec = json.loads(expected) if structured else {}
        data = page.evaluate(COLLECTION_SCRIPT, {"key": spec.get("key", "text"), "needle": ""})
        if structured:
            if kind == "LIST_SORTED":
                verdict, _actual, message = evaluate_sorted(data, spec)
            else:
                verdict, _actual, message = evaluate_filter(data, spec.get("value", ""), spec.get("domain") or [])
            if verdict == "not_evaluable":
                incomplete(message)
            assert verdict == "pass", message
        else:
            texts = data.get("texts") or []
            if not texts:
                incomplete("could not identify any listed records")
            missing = [t[:80] for t in texts if expected.lower() not in t.lower()]
            assert not missing, f"Expected every record to contain {expected!r}; non-matching: {missing[:3]}"
    elif kind == "NO_TEXT_ANOMALY":
        text = page.evaluate("() => (document.body && document.body.innerText) || ''")
        found = [p for p in TEXT_ANOMALY_PATTERNS if re.search(p, text)]
        assert not found, f"Rendered text contains anomalies matching {found}"
    elif kind == "ACCESSIBILITY_VALID":
        missing = page.evaluate("""() => { const els = Array.from(document.querySelectorAll('input:not([type="hidden"]), button, select, textarea, a[href], [role="button"], [role="link"]'));
            let missing = 0; for (const el of els) { let n = (el.getAttribute('aria-label') || el.getAttribute('aria-labelledby') || el.getAttribute('title') || el.getAttribute('placeholder') || '').trim();
            if (!n && el.labels && el.labels.length) n = (el.labels[0].textContent || '').trim();
            if (!n && el.id) { const l = document.querySelector('label[for="' + CSS.escape(el.id) + '"]'); if (l) n = (l.textContent || '').trim(); }
            if (!n && ['BUTTON', 'A'].includes(el.tagName)) n = (el.textContent || '').trim();
            if (!n && el.tagName === 'INPUT' && ['submit', 'button', 'reset'].includes((el.type || '').toLowerCase())) n = (el.value || '').trim();
            if (!n) missing++; } return {missing: missing, total: els.length}; }""")
        assert missing["missing"] <= missing["total"] * 0.2, f"{missing['missing']}/{missing['total']} controls lack accessible names"
    elif kind == "VALIDITY_VALUE_MISSING":
        res = page.evaluate("""(sel) => { const el = document.querySelector(sel); const inv = document.querySelectorAll(':invalid').length;
            return {missing: !!(el && el.validity && el.validity.valueMissing), invalid: inv}; }""", selector or "input:required")
        assert res["missing"] or res["invalid"] > 0, "Expected a required-field (valueMissing) validation state"
    elif kind == "VALIDITY_INVALID":
        assert page.evaluate("(sel) => { const el = document.querySelector(sel); return !!(el && el.checkValidity && !el.checkValidity()) || document.querySelectorAll(':invalid').length > 0; }", selector or ":invalid")
    elif kind == "FORM_SUBMISSION_BLOCKED":
        blocked = page.evaluate("() => document.querySelectorAll(':invalid').length > 0")
        assert blocked or (expected and expected.rstrip('/') in page.url), "Expected form submission to be blocked"
    elif kind == "INPUT_MASKED":
        assert page.evaluate("(sel) => { const el = document.querySelector(sel) || document.querySelector('input[type=password]'); return !!el && el.type === 'password'; }", selector or "input[type=password]")
    else:
        incomplete(f"assertion type {kind} has no exportable oracle")
"""
Collection oracles (ordering and filtering) shared by the executor and exported Playwright scripts.

Both functions take the record collection gathered in the page by COLLECTION_SCRIPT and return
(verdict, actual, message) with verdict "pass", "fail" or "not_evaluable". They depend only on `re`
so the exporter can embed this module's source verbatim and keep identical semantics.

Ordering: when the records have column headers and the sort option names a header ("Price: Low to
High" -> the "Price" column), values are read from that column only; otherwise from each record's
text. `any_direction` checks only that the order is monotonic in that key, which does not depend
on reading a direction from the option label.

Filtering: the selected option must equal the value of one of each record's own fields. The field
is identified from the data: it is the field whose value is one of the filter's options in every
record (the attribute the filter ranges over). Without such a field the result is not evaluable,
rather than falling back to a substring match on the whole record.
"""


_NUMBER_RE = re.compile(r"[$€£₹]\s*-?\d[\d,]*(?:\.\d+)?|-?\d[\d,]*(?:\.\d+)?")


def _number(text):
    text = str(text or "")
    m = re.search(r"[$€£₹]\s*-?\d[\d,]*(?:\.\d+)?", text) or re.search(r"-?\d[\d,]*(?:\.\d+)?", text)
    return float(re.sub(r"[^\d.\-]", "", m.group(0))) if m else None


def _norm(text):
    return re.sub(r"\s+", " ", str(text or "")).strip().casefold()


def column_values(data, key, column_hint):
    """Values of the column whose header contains `column_hint`; None when no such column exists."""
    headers = [_norm(h) for h in (data or {}).get("headers") or []]
    hint = _norm(column_hint)
    if not hint or not headers:
        return None
    idx = next((i for i, h in enumerate(headers) if hint in h), None)
    fields = (data or {}).get("fields") or []
    if idx is None or not fields or any(len(f) <= idx for f in fields):
        return None
    raw = [f[idx] for f in fields]
    values = [_number(v) for v in raw] if key == "number" else [str(v).strip() for v in raw]
    return values if all(v is not None and v != "" for v in values) else None


def _single_amounts(data):
    """One currency amount per record (an unambiguous numeric key without column headers), else None."""
    out = []
    for t in (data or {}).get("texts") or []:
        amounts = re.findall(r"[$\u20ac\u00a3\u20b9]\s*-?\d[\d,]*(?:\.\d+)?", str(t))
        if len(amounts) != 1:
            return None
        out.append(float(re.sub(r"[^\d.\-]", "", amounts[0])))
    return out or None


def evaluate_sorted(data, spec):
    key = spec.get("key", "text")
    values = column_values(data, key, spec.get("column_hint"))
    source = f"column '{spec.get('column_hint')}'" if values is not None else "record text"
    if values is None and spec.get("any_direction"):
        # The convention-level check needs an unambiguous key: a named column, or exactly one amount per record.
        values = _single_amounts(data) if key == "number" else None
        source = "the single amount in each record"
        if values is None:
            return "not_evaluable", None, ("the sort key could not be located unambiguously in the records "
                                           "(no matching column header; not exactly one amount per record)")
    if values is None:
        values = list((data or {}).get("values") or [])
    if len(values) < 2:
        return "not_evaluable", None, "could not identify at least two records to compare"
    sort_key = (lambda v: v) if key == "number" else (lambda v: str(v).casefold())
    asc = sorted(values, key=sort_key)
    sample = ", ".join(str(v) for v in values[:6])
    if spec.get("any_direction"):
        if values == asc or values == asc[::-1]:
            return "pass", f"{len(values)} records monotonic by {key} ({source}): {sample}", None
        return "fail", sample, f"Records are not ordered by {key} in either direction ({source}): {sample}"
    direction = spec.get("direction", "asc")
    expected = asc if direction == "asc" else asc[::-1]
    if values == expected:
        return "pass", f"{len(values)} records ordered {key} {direction} ({source}): {sample}", None
    return "fail", sample, f"Records are not ordered by {key} {direction} ({source}): {sample}"


def evaluate_filter(data, expected, domain):
    texts = (data or {}).get("texts") or []
    fields = (data or {}).get("fields") or []
    if not texts or not fields:
        return "not_evaluable", None, "could not identify any listed records"
    options = {_norm(d) for d in domain or [] if _norm(d)}
    wanted = _norm(expected)
    values = []
    for f in fields:
        in_domain = [v for v in f if _norm(v) in options]
        if not in_domain:
            return "not_evaluable", None, ("could not identify which field of each record the filter ranges over "
                                           "(a record has no field whose value is one of the filter options)")
        values.append(in_domain)
    mismatched = [texts[i][:80] for i, vals in enumerate(values) if wanted not in {_norm(v) for v in vals}]
    if mismatched:
        return "fail", f"{len(mismatched)}/{len(texts)} records have a different value", \
            f"Filter '{expected}' shows records whose value differs: {mismatched[:3]}"
    return "pass", f"all {len(texts)} records have the value '{expected}'", None


